/* =====================================================================
   photo.js — FOTO KARTU ID (tanpa file gambar terpisah)
   ---------------------------------------------------------------------
   Foto (wildanDEV.png, lengkap dengan background) disematkan langsung di kode (base64), jadi pasti tampil di Vercel,
   Netlify, GitHub Pages, atau server mana pun, tanpa folder gambar.
   - USE_REAL_PHOTO = true  -> pakai foto asli (PHOTO)
   - USE_REAL_PHOTO = false -> pakai ilustrasi avatar buatan kode (AVATAR)
   - Kalau foto gagal dimuat, otomatis memakai AVATAR.
   Mengganti foto: ubah PHOTO dengan base64 foto lain (cari "image to base64"),
   ukuran disarankan sekitar 300x400 px agar file ringan.
   ===================================================================== */
export const USE_REAL_PHOTO = true;

export const PHOTO = 'data:image/jpeg;base64,';

